import{_ as i,o as l,c as r,ah as e,j as o}from"./chunks/framework.Ck7Wg-8g.js";const p="/projects/24-Channel-Servo-Controller/en/latest/assets/image3.DJmMQS81.png",c="/projects/24-Channel-Servo-Controller/en/latest/assets/image4.DAE6D0R2.png",d="/projects/24-Channel-Servo-Controller/en/latest/assets/image5.9ntrjdh4.png",h="/projects/24-Channel-Servo-Controller/en/latest/assets/image6.DySusuDw.png",u="/projects/24-Channel-Servo-Controller/en/latest/assets/image7.D9uCGr-R.png",g="/projects/24-Channel-Servo-Controller/en/latest/assets/image8.Bftuwwjj.png",n="/projects/24-Channel-Servo-Controller/en/latest/assets/image9.9lT_oQuP.jpeg",t="/projects/24-Channel-Servo-Controller/en/latest/assets/image10.BvqwcVVU.png",a="data:image/png;base64,",m="/projects/24-Channel-Servo-Controller/en/latest/assets/image12.BaKpJ6_7.png",w=JSON.parse('{"title":"3. LSC-16 Controller Secondary Development-Arduino Development","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_Arduino_Development.md","filePath":"docs/3_Arduino_Development.md"}'),v={name:"docs/3_Arduino_Development.md"};function _(b,s,f,A,y,C){return l(),r("div",null,[...s[0]||(s[0]=[e('<h1 id="_3-lsc-16-controller-secondary-development-arduino-development" tabindex="-1">3. LSC-16 Controller Secondary Development-Arduino Development <a class="header-anchor" href="#_3-lsc-16-controller-secondary-development-arduino-development" aria-label="Permalink to &quot;3. LSC-16 Controller Secondary Development-Arduino Development&quot;">​</a></h1><h2 id="_3-1-getting-ready" tabindex="-1">3.1 Getting Ready <a class="header-anchor" href="#_3-1-getting-ready" aria-label="Permalink to &quot;3.1 Getting Ready&quot;">​</a></h2><p id="anchor_3_1_1"></p><h3 id="_3-1-1-wiring-instruction" tabindex="-1">3.1.1 Wiring Instruction <a class="header-anchor" href="#_3-1-1-wiring-instruction" aria-label="Permalink to &quot;3.1.1 Wiring Instruction&quot;">​</a></h3><p>This section employs Arduino UNO and 16-channel servo controller for development, powered by a 7.4V 2200mAh lithium battery. Connect the serial port on the 16-channel servo controller to the serial port on the Arduino UNO.</p><p>(1) Connect the battery cable to the power interface on the servo controller, and connect the lithium battery.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Connect the red wire to &quot;<strong>+</strong>&quot;, and the black wire to &quot;<strong>-</strong>&quot;. The positive and negative poles must be matched correctly.</p><img loading="lazy" height="305" width="471" src="'+p+'" class="common_img"></section><p>(2) Use female-to-female DuPont wires to connect the Arduino UNO to the controller.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Connect the TX and RX interfaces in reverse, GND to GND, and 3.3V to 3.3V.</p></section><img loading="lazy" height="365" width="632" src="'+c+'" class="common_img"><p>(3) Connect the servo to the interface 1 on the controller.</p><img loading="lazy" height="474" width="631" src="'+d+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>When using our lithium battery, connect the lithium battery interface wire with</li></ul><p>red to positive (+) and black to negative (-) to the DC port.</p><ul><li>If the interface wire is not connected to the lithium battery, do not</li></ul><p>directly connect it to the battery interface wire to avoid a short circuit between positive</p><p>and negative poles, which may cause a short circuit.</p><ul><li><p>When connecting the serial ports, make sure to connect RX and TX correctly. Please refer to the images above.</p></li><li><p>Before powering on, ensure that no metal objects come into contact with the controller. Otherwise, it may cause a short circuit and damage the controller due to its bottom pins.</p></li></ul></section><p id="anchor_3_1_2"></p><h3 id="_3-1-2-environment-configuration" tabindex="-1">3.1.2 Environment Configuration <a class="header-anchor" href="#_3-1-2-environment-configuration" aria-label="Permalink to &quot;3.1.2 Environment Configuration&quot;">​</a></h3><p>Install Arduino on PC. The software package is stored in <a href="./Appendix.html">Appendix-&gt;Arduino Installation Package</a>.</p><ul><li><strong>Add Library File</strong></li></ul><p>(1) Open Arduino IDE. Click <strong>&quot;Sketch -&gt; Include Library -&gt; Add .ZIP Library&quot;</strong> in the menu bar.</p><img loading="lazy" height="677" width="921" src="'+h+'" class="common_img"><p>(2) Locate and open the library file in <a href="./Appendix.html">Library File</a> (import before the first use).</p><img loading="lazy" height="629" width="759" src="'+u+'" class="common_img"><p>(3) Return to the IDE. When the prompt shown in the following image appears, the library file is successfully added.</p><img loading="lazy" height="593" width="856" src="'+g+'" class="common_img"><h2 id="_3-2-development-case" tabindex="-1">3.2 Development Case <a class="header-anchor" href="#_3-2-development-case" aria-label="Permalink to &quot;3.2 Development Case&quot;">​</a></h2><h3 id="_3-2-1-case-1-pwm-servo-rotation-control" tabindex="-1">3.2.1 Case 1 PWM Servo Rotation Control <a class="header-anchor" href="#_3-2-1-case-1-pwm-servo-rotation-control" aria-label="Permalink to &quot;3.2.1 Case 1 PWM Servo Rotation Control&quot;">​</a></h3><p>In this case, commands are sent to the 16-channel servo controller to control the servo rotation via the serial port.</p><ul><li><strong>Run Program</strong></li></ul><p>(1) Open the program <strong>&quot;LobotServoController.ino&quot;</strong> stored in <strong><a href="../_static/source_code/Arduino_Development.zip">Case 1 PWM Servo Rotation Control</a></strong>.</p><p>(2) After opening the program, add the library file based on <a href="#anchor_3_1_2">3.1.2 Environment Configuration-&gt;Add Library File</a>.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>You must add the library file when running the program for the first time. Otherwise, the program will report an error.</p></section><p>(3) Connect Arduino UNO to your computer with a USB cable. Select the board type as <strong>&quot;Arduino UNO&quot;</strong> and the corresponding port.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port may not be unique. Arduino IDE will add the Arduino model after the corresponding port number.</p></section><img loading="lazy" height="3000" src="'+n+'" class="common_img" width="700px"><img loading="lazy" height="618" width="867" src="'+t+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When downloading the program, the serial ports of the Arduino UNO and the servo controller should be disconnected. Otherwise, the program will fail to be downloaded.</p></section><p>(4) After Arduino UNO is connected, click <img loading="lazy" height="32" width="33" src="'+a+'">to download the program. After the download is complete, follow <a href="#anchor_3_1_1">Wiring Instruction</a> to connect the servo controller to the Arduino UNO. Then, switch the servo controller on. The servo 1 will start to rotate.</p><img loading="lazy" height="749" width="1211" src="'+m+'" class="common_img"><ul><li><strong>Program Outcome</strong></li></ul><p>After running the program, the servo will continuously rotate between the positions of 500 and 2500, with an interval of 1.5 seconds.</p><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Import the Required Function Package</p>',41),o("p",{"lineno-start":"1"},null,-1),e('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;LobotServoController.h&gt;</span></span></code></pre></div><p>The function package mainly encapsulates various function modules for the 16-channel servo controller communication. The variables and functions defined in it can be used to control the servos.</p><p>(2) Initialize Serial Port</p>',3),o("p",{"lineno-start":"3"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LobotServoController myse;     </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void setup() {</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  while(!Serial);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Instantiate the servo control object. Set the serial port baud rate to 9600.</p><p>(3) Servo Rotation Control</p>`,3),o("p",{"lineno-start":"10"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void loop() {</span></span>
<span class="line"><span>  myse.moveServo(1,500,800);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>  myse.moveServo(1,2500,800);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>After running the main program, the &quot;moveServo()&quot; function is called to rotate the servo 1 from positions 500 to 2500.</p><h3 id="_3-2-2-case-2-pwm-servo-speed-control" tabindex="-1">3.2.2 Case 2 PWM Servo Speed Control <a class="header-anchor" href="#_3-2-2-case-2-pwm-servo-speed-control" aria-label="Permalink to &quot;3.2.2 Case 2 PWM Servo Speed Control&quot;">​</a></h3><p>In this case, commands are sent to the 16-channel servo controller to control the servo rotation via the serial port.</p><ul><li><strong>Run Program</strong></li></ul><p>(1) Open the program <strong>&quot;LobotServoController.ino&quot;</strong> stored in &quot;<strong><a href="../_static/source_code/Arduino_Development.zip">Case 2 PWM Servo Speed Control</a></strong>&quot;.</p><p>(2) After opening the program, add the library file based on &quot;<a href="#anchor_3_1_2"><strong>3.1.2 Environment Configuration-&gt;Add Library File</strong></a>&quot;.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>You must add the library file when running the program for the first time. Otherwise, the program will report an error.</p></section><p>(2) Connect Arduino UNO to your computer with a USB cable. Select the board type as <strong>&quot;Arduino UNO&quot;</strong> and the corresponding port.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port may not be unique. Arduino IDE will add the Arduino model after the corresponding port number.</p></section><img loading="lazy" height="3000" src="`+n+'" class="common_img" width="700px"><img loading="lazy" height="618" width="867" src="'+t+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When downloading the program, the serial ports of the Arduino UNO and the servo controller should be disconnected. Otherwise, the program will fail to be downloaded.</p></section><p>(4) After Arduino UNO is connected, click <img loading="lazy" height="32" width="33" src="'+a+'"> to download the program. After the download is complete, follow <a href="#anchor_3_1_1">3.1.1 Wiring Instruction</a> to connect the servo controller to the Arduino UNO. Then, switch the servo controller on. The servo 1 will start to rotate.</p><ul><li><strong>Program Outcome</strong></li></ul><p>After running the program, the servo will rotate from position 500 to 2500 at a speed of 800ms. Then it will move back to position 500 at a speed of 1200ms.</p><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Import the Required Function Package</p>',18),o("p",{"lineno-start":"1"},null,-1),e('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;LobotServoController.h&gt;</span></span></code></pre></div><p>The function package mainly encapsulates various function modules for the 16-channel servo controller communication. The variables and functions defined in it can be used to control the servos.</p><p>(2) Initialize Serial Port</p>',3),o("p",{"lineno-start":"3"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LobotServoController myse;   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void setup() {</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  while(!Serial);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Instantiate the servo control object. Set the serial port baud rate to 9600.</p><p>(3) Servo Rotation Control</p>`,3),o("p",{"lineno-start":"11"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void loop() {</span></span>
<span class="line"><span>  myse.moveServo(1,500,800);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>  myse.moveServo(1,2500,800);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>  myse.moveServo(1,500,1200);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>  myse.moveServo(1,2500,1200);  </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>After running the main program, the &quot;moveServo()&quot; function is called to control the rotation position and time of the servo 1. Then, the rotation time is adjusted to control the servo speed.</p><h3 id="_3-2-3-case-3-multiple-servos-rotation-control" tabindex="-1">3.2.3 Case 3 Multiple Servos Rotation Control <a class="header-anchor" href="#_3-2-3-case-3-multiple-servos-rotation-control" aria-label="Permalink to &quot;3.2.3 Case 3 Multiple Servos Rotation Control&quot;">​</a></h3><p>In this case, commands are sent to the 16-channel servo controller to control multiple servos&#39; rotation via the serial port.</p><ul><li><strong>Run Program</strong></li></ul><p>(1) Open the program <strong>&quot;LobotServoController.ino&quot;</strong> stored in <strong><a href="../_static/source_code/Arduino_Development.zip">Case 3 Multiple Servos Rotation Control</a></strong>.</p><p>(2) After opening the program, add the library file based on &quot;Add Library File&quot;.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>You must add the library file when running the program for the first time. Otherwise, the program will report an error.</p></section><p>(3) Connect Arduino UNO to your computer with a USB cable. Select the board type as &quot;<strong>Arduino UNO</strong>&quot; and the corresponding port.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port may not be unique. Arduino IDE will add the Arduino model after the corresponding port number.</p></section><img loading="lazy" height="3000" src="`+n+'" class="common_img" width="700px"><img loading="lazy" height="618" width="867" src="'+t+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When downloading the program, the serial ports of the Arduino UNO and the servo controller should be disconnected. Otherwise, the program will fail to be downloaded.</p></section><p>(4) After Arduino UNO is connected, click <img loading="lazy" height="32" width="33" src="'+a+'"> to download the program. After the download is complete, follow &quot;<a href="#anchor_3_1_1"><strong>Wiring Instruction</strong></a>&quot; to connect the servo controller to the Arduino UNO. Then, switch the servo controller on. The servo 1 will start to rotate.</p><ul><li><strong>Program Outcome</strong></li></ul><p>After running the program, servos 1 and 2 will continuously rotate between positions 500 and 2500, at an interval of 1.5 seconds. The number of manageable servos depends on the interfaces on the controller. Let&#39;s demonstrate how to control two servos. If you want to control more servos, modify the code accordingly.</p><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Import the Required Function Package</p>',18),o("p",{"lineno-start":"1"},null,-1),e('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;LobotServoController.h&gt;</span></span></code></pre></div><p>The function package mainly encapsulates various function modules for the 16-channel servo controller communication. The variables and functions defined in it can be used to control the servos.</p><p>(2) Initialize Serial Port</p>',3),o("p",{"lineno-start":"3"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LobotServoController myse;     </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void setup() {</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  while(!Serial);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Instantiate the servo control object. Set the serial port baud rate to 9600.</p><p>(3) Servo Rotation Control</p>`,3),o("p",{"lineno-start":"10"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LobotServo servos[2];    </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void loop() {</span></span>
<span class="line"><span>  servos[0].ID = 1;        </span></span>
<span class="line"><span>  servos[0].Position = 500;   </span></span>
<span class="line"><span>  servos[1].ID = 2;        </span></span>
<span class="line"><span>  servos[1].Position = 500;   </span></span>
<span class="line"><span>  myse.moveServos(servos,2,800);   </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>  servos[0].ID = 1;        </span></span>
<span class="line"><span>  servos[0].Position = 2500;   </span></span>
<span class="line"><span>  servos[1].ID = 2;        </span></span>
<span class="line"><span>  servos[1].Position = 2500;  </span></span>
<span class="line"><span>  myse.moveServos(servos,2,800);   </span></span>
<span class="line"><span>  delay(1500);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Before running the main program, define an array to control the servos. Store the servo IDs and positions to be controlled in the array. Call the &quot;moveServos()&quot; function to send the data in the array to the servo controller, enabling multiple servos control.</p><h3 id="_3-2-4-case-4-adjust-neutral-position-and-deviation" tabindex="-1">3.2.4 Case 4 Adjust Neutral Position and Deviation <a class="header-anchor" href="#_3-2-4-case-4-adjust-neutral-position-and-deviation" aria-label="Permalink to &quot;3.2.4 Case 4 Adjust Neutral Position and Deviation&quot;">​</a></h3><p>In this case, commands are sent to the 16-channel servo controller via the serial port. Then, the servo controller controls the servo to rotate to the neutral position and deviation position.</p><p>The neutral position is assumed to be the initial position of the servo, which serves as the &quot;zero point&quot; for positive and negative angle rotation. Therefore, before installing the servo horn, the servo needs to be adjusted to the neutral position.</p><p>The servo deviation is caused by the interval between the teeth on the spline of the servo arm, which is a mechanical error. This can be adjusted through the program. In robots or robotic arms, if the deviation is not adjusted, it may restrict the movement of the robots. This affects the motion outcome.</p><ul><li><strong>Run Program</strong></li></ul><p>(1) Open the program <strong>&quot;LobotServoController.ino&quot;</strong> stored in <strong><a href="../_static/source_code/Arduino_Development.zip">Case 4 Adjust Neutral Position and Deviation</a></strong>.</p><p>(2) After opening the program, add the library file based on &quot;<a href="#anchor_3_1_2"><strong>3.1.2 Environment Configuration-&gt;Add Library File</strong></a>&quot;.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>You must add the library file when running the program for the first time. Otherwise, the program will report an error.</p></section><p>(3) Connect Arduino UNO to your computer with a USB cable. Select the board type as <strong>&quot;Arduino UNO&quot;</strong> and the corresponding port.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The port may not be unique. Arduino IDE will add the Arduino model after the corresponding port number.</p></section><img loading="lazy" height="3000" src="`+n+'" class="common_img" width="700px"><img loading="lazy" height="618" width="867" src="'+t+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When downloading the program, the serial ports of the Arduino UNO and the servo controller should be disconnected. Otherwise, the program will fail to be downloaded.</p></section><p>(4) After Arduino UNO is connected, click <img loading="lazy" height="32" width="33" src="'+a+'"> to download the program. After the download is complete, follow <a href="#anchor_3_1_1">Wiring Instruction</a> to connect the servo controller to the Arduino UNO. Then, switch the servo controller on. The servo 1 will start to rotate.</p><ul><li><strong>Program Outcome</strong></li></ul><p>The servo returns to the neutral position. After a short delay, it rotates to the deviation angle and maintains that position.</p><ul><li><strong>Program Analysis</strong></li></ul><p>(1) Import the Required Function Package</p>',20),o("p",{"lineno-start":"1"},null,-1),e('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;LobotServoController.h&gt;</span></span></code></pre></div><p>The function package mainly encapsulates various function modules for the 32-channel servo controller communication. The variables and functions defined in it can be used to control the servos.</p><p>(2) Initialize Serial Port</p>',3),o("p",{"lineno-start":"3"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LobotServoController myse;     </span></span>
<span class="line"><span></span></span>
<span class="line"><span>void setup() {</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  while(!Serial);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Instantiate the servo control object. Set the serial port baud rate to 9600.</p><p>(3) Servo Rotation Control</p>`,3),o("p",{"lineno-start":"9"},null,-1),e(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint8_t deviation;    </span></span>
<span class="line"><span>void loop() {</span></span>
<span class="line"><span>  myse.moveServo(1,1500,500);  </span></span>
<span class="line"><span>  delay(2000);</span></span>
<span class="line"><span>  deviation = 200;</span></span>
<span class="line"><span>  myse.moveServo(1,1500+deviation,200);  </span></span>
<span class="line"><span>  while(1);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Before running the main program, define the servo deviation. Rotate the servo to the neutral position. Wait for 2 seconds before adding the deviation angle to the neutral position. This allows the servo to rotate to the position corresponding to the deviation angle, and remain that position.</p>`,2)])])}const T=i(v,[["render",_]]);export{w as __pageData,T as default};
